import{_ as o,l as r,o as e,c as n,v as t,p as d,x as l,d as s,i as h,S as _}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"流匹配","description":"","frontmatter":{"title":"流匹配","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/flow-matching.md","filePath":"llm/flow-matching.md","lastUpdated":1789023840000}'),p={name:"llm/flow-matching.md"};function c(m,a,f,E,u,A){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="流匹配" tabindex="-1">流匹配 <a class="header-anchor" href="#流匹配" aria-label="Permalink to &quot;流匹配&quot;">​</a></h1><div class="epigraph"><p>不必把生成写成几百步马尔可夫去噪。学一条从噪声到数据的速度场，沿常微分方程积分即可。</p><footer>—— Lipman 等 Flow Matching for Generative Modeling；对照 Liu 等 Rectified Flow</footer></div><p><a href="/llm/ddpm">上一课</a>把生成钉在离散时间去噪。缺口是连续时间：路径可以选得更直，训练目标是匹配速度而不是逐步高斯后验。后课潜空间默认：无论扩散还是流，都仍可能先在像素上太贵，要压到 VAE 潜变量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DDPM 的 \\(T\\) 步与噪声日程是设计负担；采样是随机微分方程或离散高斯链。流匹配构造概率路径 \\(p_t\\)，其速度场 \\(u_t\\) 把简单先验（高斯）推到数据分布。网络 \\(v_\\theta(x,t)\\) 回归 \\(u_t\\)（或条件速度），训练是回归，不是对抗。Rectified Flow 强调用直线路径连噪声与样本，积分更少步。</p><p>与理解侧 <a href="/llm/clip">CLIP</a> 无关：这里没有图文对比，只有连续状态上的向量场。条件生成同样把文本嵌入送进 \\(v_\\theta\\)。</p><p><span class="marginnote">流与扩散在连续时间极限下可互通；产品差异是：训练目标（速度 vs 噪声/分数）、路径是否近直线、采样器是 ODE 还是随机。少步生成仍常靠蒸馏，见后课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>抽数据 \\(x_1\\)、先验 \\(x_0\\)、时间 \\(t\\)，在路径上取 \\(x_t\\)，回归条件速度。采样解 ODE \\(\\dot x_t=v_\\theta(x_t,t)\\)。评测仍是 FID 与条件遵守，不要用下一步交叉熵——那是离散 token 的账。</p>',9)),(e(),d(_,null,{default:l(()=>[h(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20N%5B%22%E5%85%88%E9%AA%8C%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20ODE%5B%22%E6%B2%BF%E9%80%9F%E5%BA%A6%E5%9C%BA%E7%A7%AF%E5%88%86%22%5D%0A%20%20ODE%20--%3E%20D%5B%22%E6%95%B0%E6%8D%AE%E6%A0%B7%E6%9C%AC%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>若路径是噪声与数据之间的直线，速度近似恒定，\\(v_\\theta\\) 更容易、积分步数可少。弯曲路径则把难度推给网络与求解器。这解释了为何同参数量下「直的流」少步更稳，而不是魔法替代了表示学习——表示仍由骨干与数据决定。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>流不自动给出离散视觉词表，接自回归 LLM 仍要量化或另做连续头。下一课先把昂贵的像素生成挪到潜空间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>流匹配学速度场，用 ODE 从先验走到数据。</li><li>直路径减少积分步，与 DDPM 的长链不同。</li><li>目标是回归，不是词表 CE。</li><li>出处：Lipman 等 Flow Matching；Liu 等 Rectified Flow。</li></ul>',6))])}const P=o(p,[["render",c]]);export{D as __pageData,P as default};
